mapper.select:
select o.id, o.add_time from litemall_order o left join litemall_user u on o.user_id = u.id left join litemall_order_goods og on o.id = og.order_id
${query}
group by o.id
order by ${orderByClause}

select o.id, o.order_sn, o.order_status, o.actual_price, o.freight_price, o.add_time, o.message, o.consignee, o.address, o.mobile, o.pay_time, o.order_price, o.ship_channel, o.ship_sn, u.id user_id, u.nickname user_name, u.avatar user_avatar, o.integral_price, og.id ogid, og.goods_id, og.product_id, og.goods_name, og.pic_url goods_picture, og.specifications goods_specifications, og.number goods_number, og.price goods_price from litemall_order o left join litemall_user u on o.user_id = u.id left join litemall_order_goods og on o.id = og.order_id left join litemall_goods g on og.goods_id = g.id
${query}
order by ${orderByClause}

select id, order_sn, add_time, order_status, aftersale_status, source, delivery_type,
       consignee, mobile, address, country_code,
       goods_price, freight_price, coupon_price, order_price, actual_price,
       pay_id, pay_time, ship_channel, ship_sn, user_id
from litemall_order
where deleted = 0
  and id > #{lastId}

    and user_id = #{userId}


    and order_sn = #{orderSn}


    and order_status in

        #{status}



    and add_time >= #{start}


    and add_time < #{end}

order by id asc
limit #{limit}

select coalesce(nullif(source, ''), 'local') as source, count(*) as orders, coalesce(sum(actual_price), 0) as amount from litemall_order where deleted = 0
and add_time >= #{start}
and add_time < #{end}
group by 1 order by 2 desc

select case when pay_id is null or pay_id = '' then 'UNPAID'
            else substring_index(pay_id, ':', 1) end as tender,
       count(*) as orders,
       coalesce(sum(actual_price), 0) as amount
from litemall_order
where deleted = 0

    and add_time >= #{start}


    and add_time < #{end}

group by 1
order by 2 desc
